p = Path('atendimento.html')
s = p.read_text(encoding='utf-8')

s = replace_once(s, '''    function nomeCasal(casal) {\n      const pessoa1 = casal.nome_pessoa_1 || casal.nome_noiva || "";\n      const pessoa2 = casal.nome_pessoa_2 || casal.nome_noivo || "";\n\n      if (pessoa1 && pessoa2) {\n        return pessoa1 + " ❤️ " + pessoa2;\n      }\n\n      return pessoa1 || pessoa2 || casal.nome_contato || "Casal sem nome";\n    }''', '''    function nomeCasal(casal) {\n      const pessoa1 = casal.nome_pessoa_1 || casal.nome_noiva || "";\n      const pessoa2 = casal.nome_pessoa_2 || casal.nome_noivo || "";\n\n      if (pessoa1 && pessoa2) {\n        return pessoa1 + " ❤️ " + pessoa2;\n      }\n\n      return pessoa1 || pessoa2 || casal.nome_contato || "Casal sem nome";\n    }\n\n    function ehCorporativo(casal) {\n      const tipo = String(casal && casal.tipo_evento || "").trim().toUpperCase();\n      const origem = String(casal && casal.origem || "").trim().toUpperCase();\n      return tipo === "CORPORATIVO" || origem === "META_CORPORATIVO";\n    }\n\n    function nomeRegistro(casal) {\n      if (ehCorporativo(casal)) return casal.nome_empresa || casal.nome_contato || "Empresa sem nome";\n      return nomeCasal(casal);\n    }\n\n    function formatarDataEvento(casal) {\n      if (ehCorporativo(casal)) return casal.data_evento ? "📅 " + casal.data_evento : "📅 Data não informada";\n      return formatarDataCasamento(casal.data_casamento);\n    }\n\n    function formatarQuantidadeEvento(casal) {\n      if (ehCorporativo(casal)) return casal.quantidade_pessoas ? "👥 " + casal.quantidade_pessoas + " pessoas" : "👥 Quantidade não informada";\n      return formatarConvidados(casal.quantidade_convidados);\n    }\n\n    function configurarAtendimentoPorTipo(casal) {\n      const corporativo = ehCorporativo(casal);\n      const navAtencao = document.getElementById("navAtencao");\n      const navDisponibilidade = document.getElementById("navDisponibilidade");\n      const propostaResumo = document.getElementById("propostaResumo");\n      if (navAtencao) navAtencao.style.display = corporativo ? "none" : "";\n      if (navDisponibilidade) navDisponibilidade.style.display = corporativo ? "none" : "";\n      if (propostaResumo) propostaResumo.style.display = corporativo ? "none" : "";\n      if (corporativo) {\n        const reviewDock = document.getElementById("reviewDock");\n        if (reviewDock) reviewDock.classList.remove("show", "urgent");\n      }\n      atualizarDockModoHumano();\n    }''', 'atendimento helpers multi evento')

s = replace_once(s, '''        document.getElementById("nomeCasal").textContent = nomeCasal(casal);\n        document.getElementById("dataCasamento").textContent = formatarDataCasamento(casal.data_casamento);\n        document.getElementById("qtdConvidados").textContent = formatarConvidados(casal.quantidade_convidados);\n        atualizarResumoPropostaCabecalho(casal);\n        carregarResumoPropostaCasal(casalAtualId);\n        renderizarEncantamentos(casal.encantamentos_principais);\n        await carregarHistoricoConversas({ forcar: true, forcarScroll: true });\n        iniciarAtualizacaoAutomaticaConversas();\n        await carregarRevisaoPendenteAtual({ tocarSom: false });\n        iniciarAtualizacaoAutomaticaRevisoes();\n        iniciarAlarmeRevisaoAtendimento();''', '''        const corporativo = ehCorporativo(casal);\n        document.getElementById("nomeCasal").textContent = nomeRegistro(casal);\n        document.getElementById("dataCasamento").textContent = formatarDataEvento(casal);\n        document.getElementById("qtdConvidados").textContent = formatarQuantidadeEvento(casal);\n        atualizarResumoPropostaCabecalho(casal);\n        if (!corporativo) carregarResumoPropostaCasal(casalAtualId);\n        renderizarEncantamentos(corporativo ? "" : casal.encantamentos_principais);\n        configurarAtendimentoPorTipo(casal);\n        await carregarHistoricoConversas({ forcar: true, forcarScroll: true });\n        iniciarAtualizacaoAutomaticaConversas();\n        if (!corporativo) {\n          await carregarRevisaoPendenteAtual({ tocarSom: false });\n          iniciarAtualizacaoAutomaticaRevisoes();\n          iniciarAlarmeRevisaoAtendimento();\n        } else {\n          esconderRevisaoPendente();\n        }''', 'atendimento carregar corporativo')

s = replace_once(s, '''    function atualizarDockModoHumano() {\n      const humanDock = document.getElementById("humanModeDock");\n      const modo = String(casalAtual.modo_atendimento_ia || "").toUpperCase();\n      humanDock.classList.toggle("show", modo === "HUMANO");\n    }''', '''    function atualizarDockModoHumano() {\n      const humanDock = document.getElementById("humanModeDock");\n      const humanText = document.getElementById("humanModeText");\n      const humanBtn = document.getElementById("humanModeBtn");\n      const modo = String(casalAtual.modo_atendimento_ia || "").toUpperCase();\n      const corporativo = ehCorporativo(casalAtual);\n      humanDock.classList.toggle("show", modo === "HUMANO");\n      if (corporativo) {\n        if (humanText) humanText.innerHTML = "Atendimento corporativo sob responsabilidade humana.<br>A Milene não participa desta rota.";\n        if (humanBtn) humanBtn.style.display = "none";\n      } else {\n        if (humanText) humanText.innerHTML = "Atendimento assumido pelo humano.<br>A Milene está pausada para este casal.";\n        if (humanBtn) humanBtn.style.display = "";\n      }\n    }''', 'atendimento dock humano')

s = replace_once(s, '''    async function devolverAtendimentoParaMilene() {''', '''    async function devolverAtendimentoParaMilene() {\n      if (ehCorporativo(casalAtual)) {\n        alert("Atendimentos corporativos permanecem em modo humano.");\n        return;\n      }''', 'atendimento bloquear devolver milene')

