s = replace_once(s, '''    <section class="human-mode-dock" id="humanModeDock">\n      <div class="human-mode-text">''', '''    <section class="human-mode-dock" id="humanModeDock">\n      <div class="human-mode-text" id="humanModeText">''', 'atendimento human text id')
s = replace_once(s, '''      <button class="human-mode-btn" type="button" onclick="devolverAtendimentoParaMilene()">DEVOLVER PARA MILENE</button>''', '''      <button class="human-mode-btn" id="humanModeBtn" type="button" onclick="devolverAtendimentoParaMilene()">DEVOLVER PARA MILENE</button>''', 'atendimento human btn id')
s = replace_once(s, '''      <div class="nav-item" onclick="abrirDisponibilidade()">''', '''      <div class="nav-item" id="navDisponibilidade" onclick="abrirDisponibilidade()">''', 'atendimento nav disponibilidade id')
